#include <bits/stdc++.h>
using namespace std;

struct Fenwick {
    int n;
    vector<long long> tree;

    Fenwick(int n) : n(n), tree(n + 2, 0) {}

    void add(int i, long long value) {
        for (; i <= n; i += i & -i) tree[i] += value;
    }

    long long sum(int i) const {
        long long result = 0;
        for (; i > 0; i -= i & -i) result += tree[i];
        return result;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;

    Fenwick intercepts(N + 1), slopes(N + 1);

    auto rangeAdd = [&](Fenwick& bit, int l, int r, long long value) {
        bit.add(l, value);
        bit.add(r + 1, -value);
    };

    while (M--) {
        int type, i;
        cin >> type >> i;

        if (type == 1 || type == 2) {
            long long V;
            cin >> V;

            int l, r;
            long long a, b;

            if (type == 1) {
                l = i;
                r = min<long long>(N, i + V - 1);
                a = V + i;
                b = -1;
            } else {
                l = max<long long>(1, i - V + 1);
                r = i;
                a = V - i;
                b = 1;
            }

            rangeAdd(intercepts, l, r, a);
            rangeAdd(slopes, l, r, b);
        } else {
            long long a = intercepts.sum(i);
            long long b = slopes.sum(i);
            cout << a + b * i << '\n';
        }
    }

    return 0;
}
